/**
 * Zone-combat faint tracking: slot indices (UI) + creature UIDs (swap-safe).
 */

import type { GameRuntime } from '../types/game.js';

export function resetFaintedThisCombat(game: GameRuntime): void {
    game.faintedThisCombat = new Set();
    game.faintedUidsThisCombat = new Set();
}

export function registerTeamFaintThisCombat(game: GameRuntime, teamIndex: number): void {
    if (!game.faintedThisCombat) game.faintedThisCombat = new Set();
    game.faintedThisCombat.add(teamIndex);
    if (!game.faintedUidsThisCombat) game.faintedUidsThisCombat = new Set();
    const creature = game.playerTeam?.[teamIndex];
    if (creature?.uid) game.faintedUidsThisCombat.add(creature.uid);
}

export function isCreatureFaintedThisCombat(
    game: GameRuntime,
    creature: { uid?: string } | null | undefined,
    teamIndex?: number,
): boolean {
    if (creature?.uid && game.faintedUidsThisCombat?.has(creature.uid)) return true;
    if (typeof teamIndex === 'number' && game.faintedThisCombat?.has(teamIndex)) return true;
    return false;
}

/** Rebuild slot indices from UID set after team reorder/swap. */
export function syncFaintedIndicesFromUids(game: GameRuntime): void {
    const uids = game.faintedUidsThisCombat;
    if (!uids?.size) return;
    const next = new Set<number>();
    const team = game.playerTeam;
    if (!Array.isArray(team)) return;
    for (let i = 0; i < team.length; i++) {
        const c = team[i];
        if (c?.uid && uids.has(c.uid)) next.add(i);
    }
    game.faintedThisCombat = next;
}

/** UI snapshot: current team slots for creatures KO'd this combat. */
export function buildFaintedTeamIndices(game: GameRuntime): number[] {
    const uids = game.faintedUidsThisCombat;
    if (uids?.size) {
        const indices: number[] = [];
        const team = game.playerTeam;
        if (!Array.isArray(team)) return [];
        for (let i = 0; i < team.length; i++) {
            const c = team[i];
            if (c?.uid && uids.has(c.uid)) indices.push(i);
        }
        return indices;
    }
    const legacy = game.faintedThisCombat;
    return legacy ? Array.from(legacy) : [];
}
