/**
 * @file src/lib/playerCombatRoster.ts
 * Active combat roster bounds (6 + team_slot account talents, cap 8).
 */

import type { CreatureData } from '../types/creature.js';
import type { GameRuntime } from '../types/game.js';

/** Gym badge that unlocks the ultimate mentor slot (not an account talent). */
export const ULTIMATE_SLOT_UNLOCK_BADGE = 'legend';

const MAX_TEAM_SIZE = 8;

function accountTalentBonus(game: GameRuntime, key: string): number {
  const fn = game.getAccountTalentBonus;
  if (typeof fn !== 'function') return 0;
  const n = fn.call(game, key);
  return typeof n === 'number' && Number.isFinite(n) ? n : 0;
}

/** Max active team slots (base 6 + team_slot badges, capped at 8). */
export function getMaxTeamSize(game: GameRuntime): number {
  return Math.min(MAX_TEAM_SIZE, 6 + accountTalentBonus(game, 'team_slot'));
}

/** True when the Unova Legend badge unlocks the ultimate mentor slot. */
export function isUltimateSlotUnlocked(game: GameRuntime): boolean {
  if (typeof game.hasBadge === 'function') {
    return game.hasBadge(ULTIMATE_SLOT_UNLOCK_BADGE);
  }
  return !!(game.badges?.[ULTIMATE_SLOT_UNLOCK_BADGE]);
}

/** True when the Legend-badge onboarding modal should be shown. */
export function shouldShowUltimateSlotIntro(game: GameRuntime): boolean {
  if (game.ultimateSlotIntroShown) return false;
  return isUltimateSlotUnlocked(game);
}

/** Player team members eligible for combat UI (DPS overlay, AFK bar, etc.). */
export function getPlayerCombatRoster(game: GameRuntime): CreatureData[] {
  const team = game.playerTeam;
  if (!Array.isArray(team)) return [];
  return team.slice(0, getMaxTeamSize(game));
}
