import type { GameRuntime } from '../types/game.ts';
import type { ICreature } from '../types/creature.ts';

/** Combat dresseur (arène, zone gym, Battle Subway) : stats Pokémon individuelles, pas les main stats. */
export function isTrainerBattle(game: GameRuntime | null | undefined): boolean {
    if (!game) return false;
    return !!(game.arenaState && game.arenaState.active)
        || !!(game.gymTrainerState && game.gymTrainerState.active)
        || !!(game.subwayState && game.subwayState.isActive)
        || !!(game.championsTowerState && game.championsTowerState.isActive);
}

/**
 * Calcule le ratio HP courant / HP max d'un attaquant en gérant les 3 cas
 * (ennemi / joueur en combat dresseur / joueur en zone via mainAccountCurrentHp).
 * Retourne 1 si l'info manque (pour ne jamais bloquer un move par défaut).
 */
export function getAttackerHpRatio(game: GameRuntime | null | undefined, attacker: ICreature): number {
    if (!attacker) return 1;
    if (attacker.isEnemy) {
        const max = Number(attacker.maxHp || (attacker.stats ? attacker.stats.HP : 0));
        const cur = Number(attacker.currentHP || attacker.currentHp || 0);
        return max > 0 ? (cur / max) : 1;
    }
    if (game && isTrainerBattle(game)) {
        const max = attacker.maxHp || (attacker.stats ? attacker.stats.HP : 0) || 0;
        const cur = attacker.currentHp || 0;
        return max > 0 ? (cur / max) : 1;
    }
    const max = (game && typeof game.getPlayerMaxHp === 'function') ? game.getPlayerMaxHp() : (attacker.maxHp || 0);
    const cur = attacker.mainAccountCurrentHp || 0;
    return max > 0 ? (cur / max) : 1;
}
